"""Project D public-API adapter."""

from __future__ import annotations

from dataclasses import dataclass
from importlib import import_module
from types import ModuleType
from typing import Any, Mapping

from lrp.contracts import CompatibilityError, ContractError


_REQUIRED_EXPORTS = (
    "generate_candidates",
    "number_signals_from_statistics",
    "rank_candidates",
    "select_diverse_candidates",
    "select_practical_sets",
    "validate_statistics_contract",
)


@dataclass(frozen=True, slots=True)
class CandidateAdapter:
    """Thin adapter over Project D's public package."""

    module: ModuleType

    @classmethod
    def load(cls) -> "CandidateAdapter":
        """Import and validate Project D."""

        try:
            module = import_module("lotto645_candidates")
        except ImportError as exc:
            raise CompatibilityError(
                "Project D Candidate Engine is not importable"
            ) from exc

        missing = tuple(
            name for name in _REQUIRED_EXPORTS
            if not hasattr(module, name)
        )
        if missing:
            raise CompatibilityError(
                "Candidate public API is incomplete: "
                + ", ".join(missing)
            )

        return cls(module=module)

    @property
    def version(self) -> str:
        value = getattr(self.module, "__version__", None)
        if not isinstance(value, str):
            raise CompatibilityError(
                "Candidate package does not expose __version__"
            )
        return value

    def validate_statistics(
        self,
        statistics: Mapping[int, Mapping[str, Any]],
    ) -> object:
        """Validate the Project C→D normalized statistics contract."""

        validator = getattr(
            self.module,
            "validate_statistics_contract",
        )
        return validator(statistics)

    def number_signals(
        self,
        statistics: Mapping[int, Mapping[str, Any]],
    ) -> Mapping[int, object]:
        """Convert normalized statistics to Project D NumberSignals."""

        converter = getattr(
            self.module,
            "number_signals_from_statistics",
        )
        result = converter(statistics)

        if not isinstance(result, Mapping):
            raise ContractError(
                "number_signals_from_statistics must return a mapping"
            )

        return result

    def generate_candidates(
        self,
        *args: Any,
        **kwargs: Any,
    ) -> object:
        """Delegate candidate generation."""

        generator = getattr(
            self.module,
            "generate_candidates",
        )
        return generator(*args, **kwargs)

    def rank_candidates(
        self,
        *args: Any,
        **kwargs: Any,
    ) -> object:
        """Delegate candidate ranking."""

        ranker = getattr(self.module, "rank_candidates")
        return ranker(*args, **kwargs)

    def select_diverse_candidates(
        self,
        *args: Any,
        **kwargs: Any,
    ) -> object:
        """Delegate diversity compression."""

        selector = getattr(
            self.module,
            "select_diverse_candidates",
        )
        return selector(*args, **kwargs)

    def select_practical_sets(
        self,
        *args: Any,
        **kwargs: Any,
    ) -> object:
        """Delegate practical Top-5 selection."""

        selector = getattr(
            self.module,
            "select_practical_sets",
        )
        return selector(*args, **kwargs)

